  const adminOrders = () => workspace('admin',`${heading(t('Commandes et expéditions','Orders and shipments'),t('Un paiement unique ; suivi séparé pour chaque vendeur. Les statuts sont des simulations locales.','One payment; separate tracking for each seller. Statuses are local simulations.'))}${state.orders.length?state.orders.slice().reverse().map(o=>`${orderCard(o)}<div class="step-actions">${shipmentActions(o)}</div>`).join(''):empty(t('Aucune commande simulée','No simulated orders'),t('Créez une commande depuis la boutique pour explorer le suivi central.','Create an order in the shop to explore central tracking.'))}`);
  const adminRequests = () => workspace('admin',`${heading(t('Devis et demandes de réservation','Quotes and reservation requests'),t('Pour les biens volumineux, le parcours collecte une demande. Les modalités exactes restent à préciser avec Vito.','For large goods, the journey collects an enquiry. Exact arrangements remain to be defined with Vito.'))}${state.requests.length?state.requests.slice().reverse().map(q=>`<section class="panel"><div class="panel-heading"><div><span class="eyebrow">${q.kind==='reservation'?t('Demande de réservation','Reservation request'):t('Devis','Quote')}</span><h2>${esc(label(q.productName))}</h2><p class="subtle">${esc(q.id)} · ${dateText(q.date)}</p></div><span class="chip neutral">${q.status==='reviewing'?t('En examen','Under review'):t('Nouvelle demande','New request')}</span></div><div class="spec-grid"><div class="spec-item"><span>${t('Vendeur','Seller')}</span><strong>${esc(q.vendorName)}</strong></div><div class="spec-item"><span>${t('Destination','Destination')}</span><strong>${esc(countryName(q.country))}</strong></div><div class="spec-item"><span>${t('Contact fictif','Fictional contact')}</span><strong>${esc(q.name)} · ${esc(q.email)}</strong></div><div class="spec-item"><span>${t('Date souhaitée','Desired date')}</span><strong>${q.desiredDate?esc(q.desiredDate):t('Non précisée','Not specified')}</strong></div></div>${q.note?`<p>${esc(q.note)}</p>`:''}<div class="modal-actions"><button class="button secondary" data-action="request-status" data-id="${esc(q.id)}">${t('Simuler la prise en charge','Simulate review')}</button></div><p class="form-help">${t('Aucun message envoyé. Aucun acompte, aucune réservation ni prestation confirmée.','No message sent. No deposit, reservation or service confirmed.')}</p></section>`).join(''):empty(t('Aucune demande simulée','No simulated requests'),t('Ouvrez la fiche d’un véhicule ou d’une maison préfabriquée pour essayer ce parcours.','Open a vehicle or prefabricated home listing to try this journey.'),'/catalog?mode=quote',t('Explorer les biens sur demande','Explore goods on request'))}`);
